messages.content:
Game Endless Runner edukasi tentang pengelompokan organ tubuh manusia berdasarkan sistem pencernaan, pernapasan, dan peredaran darah, dengan gaya visual Cartoon dan kesulitan Normal. Asumsi: item organ diambil dengan melompat, dan target sistem berganti setiap 5 jawaban benar.

```js
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "organ-run", title: "Organ Run — Petualangan Sistem Tubuh", seed: "organ-run-01",
  theme: { preset: "cartoon" },

  learning: {
    subject: "IPA — Organ Tubuh Manusia",
    concept: "Pengelompokan organ berdasarkan sistem pencernaan, pernapasan, dan peredaran darah",
    objectives: ["Mengelompokkan organ tubuh ke sistem yang tepat"],
    misconceptions: [
      "Jantung dianggap organ pencernaan karena letaknya di perut",
      "Paru-paru dianggap organ peredaran darah karena berhubungan dengan darah"
    ],
    mode: "category",
    categories: [
      { id: "pencernaan", label: "Pencernaan", color: "#F2994A" },
      { id: "pernapasan", label: "Pernapasan", color: "#2F80ED" },
      { id: "peredaran",  label: "Peredaran Darah", color: "#E5484D" }
    ],
    items: [
      { id: "lambung",     label: "Lambung",        category: "pencernaan", explain: "Mencerna makanan dengan enzim dan asam lambung." },
      { id: "usus-halus",  label: "Usus halus",     category: "pencernaan", explain: "Menyerap sari-sari makanan ke dalam tubuh." },
      { id: "kerongkongan",label: "Kerongkongan",   category: "pencernaan", explain: "Saluran yang mengantar makanan menuju lambung." },
      { id: "paru-paru",   label: "Paru-paru",      category: "pernapasan", explain: "Tempat pertukaran oksigen dan karbon dioksida." },
      { id: "trakea",      label: "Trakea",         category: "pernapasan", explain: "Saluran udara dari tenggorokan menuju paru-paru." },
      { id: "hidung",      label: "Hidung",         category: "pernapasan", explain: "Menyaring dan menghangatkan udara yang masuk." },
      { id: "jantung",     label: "Jantung",        category: "peredaran",  explain: "Memompa darah ke seluruh tubuh." },
      { id: "pembuluh",    label: "Pembuluh darah", category: "peredaran",  explain: "Saluran tempat darah mengalir ke seluruh tubuh." },
      { id: "arteri",      label: "Arteri",         category: "peredaran",  explain: "Pembuluh yang membawa darah keluar dari jantung." }
    ],
    target: { rotateAfterCorrect: 5, bias: 0.5 }
  },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 3, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 360, maxSpeed: 720, accel: 6 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "batu",     w: 44, h: 48, weight: 3 },
      { type: "hazard", id: "semak",    w: 90, h: 24, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: true },
    hazard:  { lives: -1, sfx: "hit", shake: 8 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 15, speed: 25 }
  }
});
// END_OF_MANIFEST
```
